import request from "graphql-request";
import { DispatchedTxnData, HashiMessageExecutionVars } from "./hashiTypes";
import { DataError, MissingEnvironmentVariable } from "../errors";

const DEFAULT_BATCH_SIZE = 10;

interface EnvioMessageDispatched {
  messageId: string;
  txHash: string;
  sourceChainId: string;
  yaho: string;
  nonce: string;
  targetChainId: string;
  threshold: string;
  sender: string;
  receiver: string;
  data: string;
  reporters: string;
  adapters: string;
  blockNumber: string;
  blockTimestamp: string;
}

interface EnvioDispatchedResponse {
  MessageDispatched: EnvioMessageDispatched[];
  chain_metadata: { latest_processed_block: number }[];
}

const dispatchedMessagesQuery = `
  query DispatchedMessages($sourceChainId: numeric!, $targetChainId: numeric!, $chainId: Int!, $yaho: String!, $fromBlock: numeric!, $limit: Int!) {
    MessageDispatched(
      where: {
        sourceChainId: { _eq: $sourceChainId }
        targetChainId: { _eq: $targetChainId }
        yaho: { _ilike: $yaho }
        blockNumber: { _gt: $fromBlock }
      }
      order_by: { blockNumber: asc }
      limit: $limit
    ) {
      messageId
      txHash
      sourceChainId
      yaho
      nonce
      targetChainId
      threshold
      sender
      receiver
      data
      reporters
      adapters
      blockNumber
      blockTimestamp
    }
    chain_metadata(where: { chain_id: { _eq: $chainId } }) {
      latest_processed_block
    }
  }
`;

/**
 * Map an Envio MessageDispatched row to the executor's HashiMessageExecutionVars shape.
 * @param row The raw MessageDispatched entity returned by the Envio indexer
 * @returns The HashiMessageExecutionVars for the executor
 */
function toHashiMessageExecutionVars(row: EnvioMessageDispatched): HashiMessageExecutionVars {
  return {
    txHash: row.txHash,
    timestamp: Number(row.blockTimestamp),
    blockNumber: Number(row.blockNumber),
    messageId: BigInt(row.messageId),
    message: {
      nonce: Number(row.nonce),
      sender: row.sender,
      targetChainId: Number(row.targetChainId),
      receiver: row.receiver,
      threshold: Number(row.threshold),
      data: row.data,
      reporters: JSON.parse(row.reporters),
      adapters: JSON.parse(row.adapters),
    },
  };
}

/**
 * Get MessageDispatched events from the Envio Yaho indexer starting after a specific block
 * @param sourceChainId The chain ID of the Yaho (source) chain
 * @param targetChainId The chain ID the messages are destined for; other routes' messages are excluded
 * @param yahoAddress The Yaho contract address
 * @param fromBlock The last processed block number; only events strictly after it are returned
 * @param batchSize The maximum number of messages to fetch (default: 10)
 * @returns The dispatched messages and the block number to checkpoint in the state file
 */
async function getDispatchedMessagesFromEnvio(
  sourceChainId: number,
  targetChainId: number,
  yahoAddress: string,
  fromBlock: number,
  batchSize = DEFAULT_BATCH_SIZE
): Promise<DispatchedTxnData> {
  const envioEndpoint = process.env.RELAYER_ENVIO_YAHO;
  if (!envioEndpoint) {
    throw new MissingEnvironmentVariable("RELAYER_ENVIO_YAHO");
  }
  try {
    const result = (await request(envioEndpoint, dispatchedMessagesQuery, {
      sourceChainId,
      targetChainId,
      chainId: sourceChainId,
      yaho: yahoAddress,
      fromBlock,
      limit: batchSize,
    })) as EnvioDispatchedResponse;

    const txns = result.MessageDispatched.map(toHashiMessageExecutionVars);

    // A full batch may have been truncated mid-range, so only checkpoint up to
    // the last fetched message; otherwise the indexer head is safe to checkpoint.
    const indexerHead = result.chain_metadata[0]?.latest_processed_block;
    let toBlock = fromBlock;
    if (txns.length === batchSize) {
      toBlock = txns[txns.length - 1].blockNumber;
    } else if (indexerHead !== undefined) {
      toBlock = Math.max(indexerHead, fromBlock);
    } else if (txns.length > 0) {
      toBlock = txns[txns.length - 1].blockNumber;
    }

    return { txns, toBlock };
  } catch (e) {
    throw new DataError("Failed to fetch dispatched messages (envio)", sourceChainId, "hashi", { cause: e });
  }
}

export { getDispatchedMessagesFromEnvio, toHashiMessageExecutionVars, EnvioMessageDispatched };

import request from "graphql-request";
import { getDispatchedMessagesFromEnvio, toHashiMessageExecutionVars, EnvioMessageDispatched } from "./envioQueries";

jest.mock("graphql-request", () => ({
  __esModule: true,
  default: jest.fn(),
}));

const mockRequest = request as jest.MockedFunction<typeof request>;

const makeEnvioRow = (overrides: Partial<EnvioMessageDispatched> = {}): EnvioMessageDispatched => ({
  messageId: "12345",
  txHash: "0xTxHash",
  sourceChainId: "1514",
  yaho: "0xYAHO",
  nonce: "3",
  targetChainId: "42161",
  threshold: "2",
  sender: "0xSender",
  receiver: "0xReceiver",
  data: "0xData",
  reporters: JSON.stringify(["0xReporter1"]),
  adapters: JSON.stringify(["0xAdapter1", "0xAdapter2"]),
  blockNumber: "100",
  blockTimestamp: "1700000000",
  ...overrides,
});

describe("envioQueries", () => {
  const sourceChainId = 1514;
  const targetChainId = 42161;
  const yahoAddress = "0xYAHO";
  const fromBlock = 50;

  beforeEach(() => {
    jest.clearAllMocks();
    process.env.RELAYER_ENVIO_YAHO = "http://envio.test/v1/graphql";
  });

  afterAll(() => {
    delete process.env.RELAYER_ENVIO_YAHO;
  });

  describe("toHashiMessageExecutionVars", () => {
    it("should map an Envio row to HashiMessageExecutionVars", () => {
      const mapped = toHashiMessageExecutionVars(makeEnvioRow());
      expect(mapped).toEqual({
        txHash: "0xTxHash",
        timestamp: 1700000000,
        blockNumber: 100,
        messageId: BigInt(12345),
        message: {
          nonce: 3,
          sender: "0xSender",
          targetChainId: 42161,
          receiver: "0xReceiver",
          threshold: 2,
          data: "0xData",
          reporters: ["0xReporter1"],
          adapters: ["0xAdapter1", "0xAdapter2"],
        },
      });
    });
  });

  describe("getDispatchedMessagesFromEnvio", () => {
    it("should throw MissingEnvironmentVariable when RELAYER_ENVIO_YAHO is not set", async () => {
      delete process.env.RELAYER_ENVIO_YAHO;
      await expect(
        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
      ).rejects.toThrow("Missing environment variable: RELAYER_ENVIO_YAHO");
      expect(mockRequest).not.toHaveBeenCalled();
    });

    it("should query the indexer with the source chain, yaho address and fromBlock", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [{ latest_processed_block: 200 }],
      });
      await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
      expect(mockRequest).toHaveBeenCalledWith("http://envio.test/v1/graphql", expect.any(String), {
        sourceChainId,
        targetChainId,
        chainId: sourceChainId,
        yaho: yahoAddress,
        fromBlock,
        limit: 10,
      });
    });

    it("should checkpoint the indexer head when the batch is not full", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [makeEnvioRow()],
        chain_metadata: [{ latest_processed_block: 200 }],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(1);
      expect(txns[0].message.nonce).toBe(3);
      expect(toBlock).toBe(200);
    });

    it("should checkpoint the last fetched message when the batch is full", async () => {
      const rows = Array.from({ length: 10 }, (_, i) =>
        makeEnvioRow({ nonce: String(i), blockNumber: String(100 + i) })
      );
      mockRequest.mockResolvedValue({
        MessageDispatched: rows,
        chain_metadata: [{ latest_processed_block: 500 }],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(10);
      expect(toBlock).toBe(109);
    });

    it("should not move the checkpoint backwards when the indexer head lags fromBlock", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [{ latest_processed_block: 40 }],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(0);
      expect(toBlock).toBe(fromBlock);
    });

    it("should checkpoint the last fetched message when chain metadata is missing", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [makeEnvioRow({ blockNumber: "120" })],
        chain_metadata: [],
      });
      const { toBlock } = await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
      expect(toBlock).toBe(120);
    });

    it("should keep fromBlock when there are no messages and no chain metadata", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(0);
      expect(toBlock).toBe(fromBlock);
    });

    it("should wrap indexer failures in DataError", async () => {
      mockRequest.mockRejectedValue(new Error("connection refused"));
      await expect(
        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
      ).rejects.toMatchObject({
        name: "DataError",
        message: "Data error for call: Failed to fetch dispatched messages (envio), Chain ID: 1514, Network: hashi",
      });
    });
  });
});

